import { describe, it, expect } from "vitest";
import { createFreeCamera } from "@babylonjs/lite";
import { labelPosition } from "./label-position";

const canvas = { width: 800, height: 600, clientWidth: 400, clientHeight: 300 } as unknown as HTMLCanvasElement;

describe("labelPosition", () => {
    it("cases", () => {
        const cam = createFreeCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 1 });
        cam.fov = 0.8; cam.nearPlane = 0.1; cam.farPlane = 1000;
        const out: Record<string, unknown> = {};
        out.center = labelPosition(cam, canvas, { x: 0, y: 0, z: 10 });
        out.behind = labelPosition(cam, canvas, { x: 0, y: 0, z: -10 });
        out.far = labelPosition(cam, canvas, { x: 0, y: 0, z: 5000 });
        out.right = labelPosition(cam, canvas, { x: 100, y: 0, z: 10 });
        out.up = labelPosition(cam, canvas, { x: 0, y: 100, z: 10 });
        out.sideways = labelPosition(cam, canvas, { x: 10, y: 0, z: 0.001 });
        out.nan = labelPosition(cam, canvas, { x: NaN, y: 0, z: 10 });
        console.log(JSON.stringify(out, null, 1));
        expect((out.center as any).visible).toBe(true);
        expect((out.behind as any).visible).toBe(false);
        expect((out.far as any).visible).toBe(true);
        expect((out.right as any).visible).toBe(false);
        expect((out.right as any).x).toBeGreaterThan(400);
        expect((out.up as any).y).toBeLessThan(150);
    });
    it("floating origin", () => {
        const cam = createFreeCamera({ x: 1000000, y: 0, z: 1000000 }, { x: 1000000, y: 0, z: 1000001 });
        cam.fov = 0.8; cam.nearPlane = 0.1; cam.farPlane = 1000;
        cam._useFloatingOrigin = true;
        const r = labelPosition(cam, canvas, { x: 1000000, y: 0, z: 1000010 });
        console.log("FO", JSON.stringify(r));
        expect(r.visible).toBe(true);
        expect(r.x).toBeCloseTo(200, 3);
    });
});
